// Yaygın Arapça yazılışlar. Ebced değerleri yazılış farklarına göre değişebilir.
const esmaArabic=`الله,الرحمن,الرحيم,الملك,القدوس,السلام,المؤمن,المهيمن,العزيز,الجبار,المتكبر,الخالق,البارئ,المصور,الغفار,القهار,الوهاب,الرزاق,الفتاح,العليم,القابض,الباسط,الخافض,الرافع,المعز,المذل,السميع,البصير,الحكم,العدل,اللطيف,الخبير,الحليم,العظيم,الغفور,الشكور,العلي,الكبير,الحفيظ,المقيت,الحسيب,الجليل,الكريم,الرقيب,المجيب,الواسع,الحكيم,الودود,المجيد,الباعث,الشهيد,الحق,الوكيل,القوي,المتين,الولي,الحميد,المحصي,المبدئ,المعيد,المحيي,المميت,الحي,القيوم,الواجد,الماجد,الواحد,الصمد,القادر,المقتدر,المقدم,المؤخر,الأول,الآخر,الظاهر,الباطن,الوالي,المتعالي,البر,التواب,المنتقم,العفو,الرؤوف,مالك الملك,ذو الجلال والإكرام,المقسط,الجامع,الغني,المغني,المانع,الضار,النافع,النور,الهادي,البديع,الباقي,الوارث,الرشيد,الصبور`.split(',');
const abjadMap={ا:1,أ:1,إ:1,آ:1,ء:1,ؤ:6,ئ:10,ب:2,ج:3,د:4,ه:5,ة:5,و:6,ز:7,ح:8,ط:9,ي:10,ى:10,ك:20,ل:30,م:40,ن:50,س:60,ع:70,ف:80,ص:90,ق:100,ر:200,ش:300,ت:400,ث:500,خ:600,ذ:700,ض:800,ظ:900,غ:1000};
function ebcedValue(arabic){let word=arabic.replace(/(^|\s)ال(?=[\u0621-\u064a])/g,'$1');return [...word].reduce((n,c)=>n+(abjadMap[c]||0),0)}
function renderEsmaDetails(panel){
 const help=document.createElement('p');help.className='hint';help.textContent='İsme dokun: kısa anlam ve ebced değerini gör. Yanındaki kutu ile öğrendiklerini işaretle. Ebced hesapları yaygın yazılışa göredir; farklı geleneklerde değişebilir.';panel.append(help);
 const list=document.createElement('div');list.className='esma-list';
 esmaNames.forEach((name,i)=>{const key='esma:'+(i+1),row=document.createElement('div');row.className='esma-row';
 const cb=document.createElement('input');cb.type='checkbox';cb.checked=check(key);cb.setAttribute('aria-label',name+' tamamlandı');cb.onchange=()=>{setCheck(key,cb.checked);panel.dispatchEvent(new Event('esma-update'))};
 const b=document.createElement('button');b.className='esma-name';b.type='button';b.textContent=(i+1)+'. '+name;b.setAttribute('aria-expanded','false');
 const details=document.createElement('div');details.className='esma-detail hidden';let meaning=esmaMeanings[i]||'Kısa anlam hazırlanıyor';if(i===0)meaning='Tek ve gerçek ilah';
 details.innerHTML='<strong>Anlamı:</strong> '+safe(meaning)+'<br><strong>Ebced:</strong> '+ebcedValue(esmaArabic[i]||'')+' <span class="hint">(başındaki “el/er” takısı hariç)</span>';
 b.onclick=()=>{details.classList.toggle('hidden');b.setAttribute('aria-expanded',String(!details.classList.contains('hidden')))};
 row.append(cb,b,details);list.append(row)});panel.append(list);
 panel.addEventListener('esma-update',()=>{const status=panel.querySelector('.live-progress');if(status){let done=esmaNames.filter((_,i)=>check('esma:'+(i+1))).length;status.textContent=`Tamamlanan: ${done} / ${esmaNames.length} · %${Math.round(done/esmaNames.length*100)}`}});
}
function addNafileProgress(panel){let status=document.createElement('p');status.className='hint';panel.insertBefore(status,panel.firstChild.nextSibling);const names=['2 Rekât Teheccüd','2 Rekât Hacet','4 Rekât Kuşluk','2 Rekât Şükür','2 Rekât İstihare','2 Rekât Tevbe'];function update(){let n=0;for(let name of names)for(let i=1;i<=30;i++)if(check('nafile:'+name+':'+i))n++;status.textContent=`Tamamlanan: ${n} / 180 · %${Math.round(n/180*100)}`};panel.addEventListener('click',e=>{if(e.target.closest('button.cell'))queueMicrotask(update)});update()}
function renderHomeIndex(){let root=$('homePdfIndex');if(!root)return;root.replaceChildren();const panel=createPanel(root,'PDF’nin 28 sayfalık içerik rehberi','Ajandayı açınca bütün sayfalara buradan ulaşabilirsin.');const list=document.createElement('div');list.className='pageindex';pdfPages.forEach((title,i)=>{let b=document.createElement('button');b.type='button';b.textContent=(i+1)+'. '+title;b.onclick=()=>{show(pageDest[i]);const anchors={0:'esmaPanel',1:'duaPanel',4:'prophetPanel',19:'kevserPanel',26:'nafilePanel',27:'kaza46Panel'};let target=anchors[i];if(target)requestAnimationFrame(()=>document.getElementById(target)?.scrollIntoView({behavior:'smooth',block:'start'}))};list.append(b)});panel.append(list)}



function renderHomeProphetShortcut(){
 const root=$('homeProphetShortcut');if(!root)return;root.replaceChildren();
 const panel=createPanel(root,'Peygamberlerin Hayatları · 25 Peygamber','Peygamber seçerek hayatını bölüm bölüm oku.');
 const select=document.createElement('select');select.setAttribute('aria-label','Peygamber seç');
 prophets.forEach((name,i)=>{const o=document.createElement('option');o.value=name;o.textContent=(i+1)+'. '+name;select.append(o)});
 const button=document.createElement('button');button.type='button';button.className='primary';button.textContent='Seçilen peygamberin hayatını oku →';button.onclick=()=>openProphet(select.value);
 const all=document.createElement('button');all.type='button';all.className='secondary';all.textContent='25 peygamberi listele';all.onclick=()=>{show('more');requestAnimationFrame(()=>document.getElementById('prophetPanel')?.scrollIntoView({block:'start'}))};
 panel.append(select,button,all);
}

// V3.3: Peygamberlerin hayatları için ayrı üç sayfalık okuyucu.
// V3.4: Ayrıntılı peygamber biyografileri ayrı JSON dosyasından yüklenir.
const prophetStories = {"Âdem":[{"title":"Hayatı ve başlangıç","body":"Allah’ın yarattığı ilk insan ve peygamber olarak anılır. Kur’an’da yaratılışı, kendisine isimlerin öğretilmesi ve meleklere verilen secde emri anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Âdem ve eşi cennette yaşarken yasaklanan ağaca yaklaşmaları üzerine yeryüzü hayatı başlar. Kur’an, onların hatalarını fark edip Allah’a yöneldiklerini bildirir.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Âdem kıssası insanın bilgi, sorumluluk, özgür irade ve tövbe ile ilişkisini hatırlatır. Kaynaklar: Bakara 2:30–39; A’râf 7:19–27; Tâhâ 20:115–123.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"İdris":[{"title":"Hayatı ve başlangıç","body":"Kur’an’da İdris, doğruluğuyla tanınan bir peygamber olarak zikredilir. Hayatının ayrıntıları hakkında Kur’an’da sınırlı bilgi vardır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Meryem suresinde onun “sıddîk” ve peygamber olduğu, yüksek bir makama yükseltildiği bildirilir. Enbiyâ suresinde sabredenler arasında sayılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"İdris’in kıssasında doğruluk, sabır ve Allah’a bağlılık öne çıkar. Kesin olmayan tarihî rivayetleri hayat hikâyesi gibi sunmamak gerekir. Kaynaklar: Meryem 19:56–57; Enbiyâ 21:85–86.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Nuh":[{"title":"Hayatı ve başlangıç","body":"Nuh, kavmini uzun süre tevhid inancına çağıran peygamberdir. Kur’an’da davetinin açık ve gizli biçimlerde sürdüğü anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Kavminin çoğu çağrısına karşı çıkar. Allah’ın emriyle gemi hazırlanır; tufan sırasında iman edenler korunur. Oğluyla ilgili anlatım, yakınlığın tek başına kurtuluş sağlamadığını vurgular.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Nuh kıssası sebat, tebliğ, sabır ve kişisel sorumluluk dersleri içerir. Kaynaklar: Hûd 11:25–49; Nuh 71:1–28.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Hûd":[{"title":"Hayatı ve başlangıç","body":"Hûd, Âd kavmine gönderilen peygamberdir. Kavmi güç ve refahıyla övünürken Hûd onları Allah’a kulluğa ve ölçülü yaşamaya çağırır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Âd kavminin ileri gelenleri bu çağrıya karşı çıkar. Kur’an, kibir ve inkârın ardından gelen yıkıcı rüzgârdan söz eder.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Hûd kıssası maddî gücün ahlâkî sorumluluğun yerine geçemeyeceğini anlatır. Kaynaklar: A’râf 7:65–72; Hûd 11:50–60; Ahkâf 46:21–26.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Sâlih":[{"title":"Hayatı ve başlangıç","body":"Sâlih, Semûd kavmine gönderilen peygamberdir. Kavmini Allah’a kulluğa ve yeryüzünde bozgunculuk yapmamaya davet eder.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Kavmine bir işaret olarak dişi deve verildiği anlatılır. Uyarılara rağmen deveyi öldüren topluluk, yaptıklarının sonucuyla karşılaşır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Sâlih kıssası emanet, sınır tanıma ve uyarıları ciddiye alma konularını öne çıkarır. Kaynaklar: A’râf 7:73–79; Hûd 11:61–68; Şems 91:11–15.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"İbrahim":[{"title":"Hayatı ve başlangıç","body":"İbrahim, tevhid inancının güçlü temsilcilerindendir. Kur’an’da putperestliğe karşı aklî sorgulamaları ve babasıyla konuşmaları anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Kavmiyle mücadelesi, ateşe atılması, hicreti ve ailesiyle ilgili sınanmaları farklı surelerde yer alır. İsmail ile Kâbe’nin temellerini yükselttikleri bildirilir.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"İbrahim kıssası tevhid, teslimiyet, misafirperverlik ve dua üzerinde düşünmeye çağırır. Kaynaklar: Enbiyâ 21:51–70; Bakara 2:124–129; Sâffât 37:99–113.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Lût":[{"title":"Hayatı ve başlangıç","body":"Lût, ahlâkî yozlaşmanın yaygınlaştığı bir topluluğa gönderilen peygamberdir. Kavmini kötülüklerden uzaklaşmaya çağırır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Kur’an’da kavminin uyarıları reddettiği, misafirleriyle ilgili bir imtihan yaşandığı ve sonunda Lût ile iman edenlerin kurtarıldığı anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Lût kıssası ahlâk, misafir güvenliği, toplumsal sorumluluk ve zulme karşı durma açısından okunabilir. Kaynaklar: Hûd 11:77–83; Ankebût 29:28–35.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"İsmail":[{"title":"Hayatı ve başlangıç","body":"İsmail, İbrahim’in oğludur. Kur’an’da sözünde duran, ailesine namaz ve zekâtı emreden bir peygamber olarak anılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"İbrahim ile birlikte Kâbe’nin temellerini yükselttikleri anlatılır. Kurbanla ilgili sınanma kıssasında teslimiyet ve sabır öne çıkar.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"İsmail’in hayatı aile içinde ibadet bilinci, verilen sözü tutma ve Allah’a güvenme temalarıyla hatırlanır. Kaynaklar: Bakara 2:125–129; Meryem 19:54–55; Sâffât 37:102–107.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"İshak":[{"title":"Hayatı ve başlangıç","body":"İshak, İbrahim’e müjdelenen oğludur. Kur’an’da onun peygamberliği ve soyundan gelen hayırlı nesiller anılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"İbrahim’e gelen misafirlerin İshak’ı müjdelemesi farklı surelerde anlatılır. İshak’ın ayrıntılı günlük hayatı hakkında Kur’an’da geniş bir anlatım bulunmaz.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"İshak kıssası ilahî rahmet, aile duası ve nesiller arası sorumluluk temalarını düşündürür. Kaynaklar: Hûd 11:69–73; Sâffât 37:112–113.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Yakub":[{"title":"Hayatı ve başlangıç","body":"Yakub, İshak’ın oğlu ve Yusuf’un babasıdır. Kur’an’da ailesiyle yaşadığı sınanmalar ve derin sabrı anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Yusuf’tan ayrı kaldığında büyük üzüntü yaşar; buna rağmen Allah’ın rahmetinden umut kesmez. Sonunda ailesiyle kavuşması anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Yakub’un hayatı sabrın duygusuzluk olmadığını; acı içinde de umut ve duanın sürdürülebileceğini gösterir. Kaynak: Yusuf 12:6–100.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Yusuf":[{"title":"Hayatı ve başlangıç","body":"Yusuf, çocukluğunda gördüğü rüyayı babası Yakub’a anlatır. Kardeşlerinin kıskançlığı nedeniyle kuyuda bırakılır ve Mısır’a götürülür.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"İftiraya uğrar, hapse girer; rüya yorumlama yeteneğiyle tanınır. Sonra ülkenin kıtlık hazırlıklarında önemli görev üstlenir.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Yusuf, güce kavuştuğunda kardeşlerini bağışlar. Kıssa sabır, iffet, adalet ve affetmeyi öne çıkarır. Kaynak: Yusuf suresi 12:1–111.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Eyyûb":[{"title":"Hayatı ve başlangıç","body":"Eyyûb, ağır sıkıntılar karşısında sabrıyla anılan peygamberdir. Kur’an, başına gelen zararın ayrıntılarını uzun uzun saymaz.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Eyyûb, Rabbine sıkıntısını arz eder. Allah’ın onun duasını kabul ettiği ve kendisine rahmet verdiği bildirilir.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Eyyûb kıssası zorlukta dua, sabır ve umut dersleri içerir. Kaynaklar: Enbiyâ 21:83–84; Sâd 38:41–44.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Şuayb":[{"title":"Hayatı ve başlangıç","body":"Şuayb, Medyen halkına gönderilen peygamberdir. Kavmini Allah’a kulluğa, ölçü ve tartıda dürüstlüğe çağırır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Toplumunda ekonomik haksızlık ve insanların hakkını eksiltme eleştirilir. Bir kısmı onun uyarılarını reddeder.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Şuayb kıssası ticarette adalet, güven ve toplumsal ahlâkın önemini hatırlatır. Kaynaklar: A’râf 7:85–93; Hûd 11:84–95.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Musa":[{"title":"Hayatı ve başlangıç","body":"Musa, İsrailoğullarına gönderilen büyük peygamberlerdendir. Firavun’un baskısı altında doğduğu ve annesinin onu korumak için nehre bıraktığı anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Allah’ın görevlendirmesiyle Firavun’u hakka çağırır. Harun kendisine yardımcı olur. Denizden geçiş, vahiy ve kavminin yolculuğu Kur’an’da geniş yer tutar.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Musa kıssası özgürlük, adalet, liderlik, sabır ve vahye bağlılık temalarını işler. Kaynaklar: Kasas 28:3–46; Tâhâ 20:9–98; A’râf 7:103–160.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Harun":[{"title":"Hayatı ve başlangıç","body":"Harun, Musa’nın kardeşi ve peygamberdir. Musa, tebliğ görevinde kendisine yardımcı olması için Harun’u ister.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Harun, İsrailoğullarına rehberlik eder. Buzağıya yönelme olayında kavmini uyarmaya çalıştığı anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Harun kıssası kardeşlik, dayanışma, iletişim ve topluluk içindeki sorumluluğu hatırlatır. Kaynaklar: Tâhâ 20:29–36, 90–94; A’râf 7:142–151.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Zülkifl":[{"title":"Hayatı ve başlangıç","body":"Zülkifl, Kur’an’da sabırlı ve iyi kimseler arasında adı geçen bir şahsiyettir. Kur’an onun hayatının ayrıntılarını açıklamaz.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Enbiyâ ve Sâd surelerinde İsmail ve İdris gibi isimlerle birlikte anılır. Peygamberliği ve tarihî kimliği hakkında yorum farklılıkları bulunur.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Bu nedenle kesin olmayan olayları ona ait tarihî gerçekler gibi anlatmamak gerekir. Öne çıkan ders sabır ve dürüstlüktür. Kaynaklar: Enbiyâ 21:85–86; Sâd 38:48.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Davud":[{"title":"Hayatı ve başlangıç","body":"Davud, hem peygamber hem yönetici olarak anılır. Kur’an’da kendisine Zebur verildiği ve hikmetle desteklendiği bildirilir.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Adaletle hükmetmesi, Allah’ı tesbihi ve demiri işleme nimeti anlatılır. Bazı kıssalarda karar verirken hakkaniyetli olma sorumluluğu vurgulanır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Davud kıssası güç ve yetkinin adalet, ibadet ve tevazu ile birlikte yürütülmesini öğütler. Kaynaklar: Sâd 38:17–26; Sebe 34:10–11; İsrâ 17:55.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"Süleyman":[{"title":"Hayatı ve başlangıç","body":"Süleyman, Davud’un oğlu ve peygamber-yöneticidir. Kur’an’da kendisine verilen özel imkânlar ve hikmet anlatılır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Kıssası ve önemli olaylar","body":"Karınca vadisi, Hüdhüd kuşu ve Sebe melikesiyle ilgili anlatılar onun hükümranlığı içinde yer alır. Nimeti Allah’a bağlaması vurgulanır.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"},{"title":"Dersler ve Kur’an kaynakları","body":"Süleyman kıssası yönetimde hikmet, şükür ve güç karşısında tevazu dersleri taşır. Kaynaklar: Neml 27:15–44; Sebe 34:12–14.","source":"Kur’an temelli özet · Ayrıntılı ayetler metinde"}],"İlyas":[{"title":"Peygamber olarak gönderilmesi","body":"İlyas Allah’ın gönderdiği elçilerdendir. Kur’an onu salih kullar arasında anar. Doğum tarihi, ailesi ve gönderildiği şehrin adı Kur’an’da verilmez.","source":"Kur’an · Sâffât 37:123; En’âm 6:85"},{"title":"Ba’l putuna karşı çağrısı","body":"Kavmine Ba’l’e mi yalvardıklarını ve en güzel yaratıcı olan Allah’ı mı terk ettiklerini sordu. Allah’ın hem kendilerinin hem de atalarının Rabbi olduğunu hatırlattı.","source":"Kur’an · Sâffât 37:124–126"},{"title":"Kavminin inkârı","body":"Kavmi onu yalanladı; ancak Allah’ın ihlaslı kulları bu durumdan ayrı tutuldu. Kur’an, kavminin uğradığı cezanın ayrıntılı biçimini anlatmaz.","source":"Kur’an · Sâffât 37:127–128"},{"title":"Allah’ın övgüsü","body":"İlyas’ın sonraki nesiller arasında güzel biçimde anıldığı, üzerine selam olduğu ve iyilik yapanlardan bulunduğu bildirildi. Sonraki hayatı ve vefatı açıklanmaz.","source":"Kur’an · Sâffât 37:129–132"}],"Elyesa":[{"title":"Allah’ın seçkin kulu","body":"Elyesa Kur’an’da adı geçen peygamberler arasındadır. İsmail, Yunus ve Lût ile birlikte anılır; Allah’ın kendilerini üstün kıldığı bildirilir.","source":"Kur’an · En’âm 6:86"},{"title":"Hayırlı kimselerden olması","body":"Sâd suresinde İsmail ve Zülkifl ile birlikte hayırlı kullar arasında anılır. Bu ayet onun yüksek manevi değerini gösterir.","source":"Kur’an · Sâd 38:48"},{"title":"Kur’an’da anlatılmayanlar","body":"Elyesa’nın mucizeleri, yaşadığı şehir, İlyas ile ilişkisinin ayrıntıları ve vefatı Kur’an’da anlatılmaz. Öğrencilik veya haleflik anlatımları tarihî ve tefsir geleneğindendir.","source":"Kaynak notu · En’âm 6:86; Sâd 38:48"}],"Yunus":[{"title":"Peygamberlik ve kavmi","body":"Yunus Allah’ın gönderdiği elçilerdendir. Kavmi başlangıçta iman etmedi. Ninova adı gelenekte yaygındır; Kur’an şehrin adını vermez.","source":"Kur’an · Sâffât 37:139; Yûnus 10:98"},{"title":"Kavminden ayrılması","body":"Yunus öfkeli bir hâlde ayrıldı. Bu ayrılışın ayrıntılı sebebi ve Allah’tan izin bekleme meselesi tefsirlerde açıklanır; Kur’an bütün ayrıntıları bildirmez.","source":"Kur’an · Enbiyâ 21:87; Kalem 68:48"},{"title":"Gemi ve kura","body":"Yüklü bir gemiye bindi. Kuraya katıldı ve kaybedenlerden oldu. Kur’an geminin rotasını, kuranın gerekçesini ve gemidekilerin sayısını belirtmez.","source":"Kur’an · Sâffât 37:140–141"},{"title":"Büyük balığın yutması","body":"Büyük bir balık onu yuttu. Kur’an balığın türünü, içinde kaç gün kaldığını ve tam yerini açıklamaz. Bu olay Yunus için büyük bir imtihandı.","source":"Kur’an · Sâffât 37:142"},{"title":"Karanlıklar içindeki dua","body":"Yunus şöyle dua etti: «Lâ ilâhe illâ ente sübhâneke innî küntü minez-zâlimîn.» Anlamı: «Senden başka ilah yoktur. Seni eksikliklerden uzak tutarım. Gerçekten ben zalimlerden oldum.» Dua tevhid, tesbih ve kusuru kabul etmeyi birleştirir.","source":"Kur’an · Enbiyâ 21:87"},{"title":"Duanın kabulü","body":"Allah Yunus’un duasını kabul ederek onu kederden kurtardı. Allah’ı tesbih edenlerden olmasaydı yeniden diriliş gününe kadar balığın karnında kalacağı bildirildi.","source":"Kur’an · Enbiyâ 21:88; Sâffât 37:143–144"},{"title":"Kıyıya çıkarılması ve bitki","body":"Yunus hasta bir hâlde açık bir yere çıkarıldı. Allah üzerinde yaktîn türünden bir bitki yetiştirdi. Bunun kabakgillerle ilişkili olduğu yaygın yorumdur.","source":"Kur’an · Sâffât 37:145–146"},{"title":"Yüz bin veya daha fazla kişi","body":"Allah’ın onu yüz bin veya daha fazla kişiye gönderdiği bildirildi. Kur’an olayların kesin tarihî sırasını bütün ayrıntılarıyla vermez.","source":"Kur’an · Sâffât 37:147"},{"title":"Kavmin iman edip tövbe etmesi","body":"Yunus’un kavmi iman etti. Allah dünya hayatındaki aşağılayıcı azabı üzerlerinden kaldırdı ve bir süre daha yaşamalarını sağladı. Halkın şehir dışına çıkması gibi ayrıntılar Kur’an’da açıkça bulunmaz.","source":"Kur’an · Yûnus 10:98; Sâffât 37:148"},{"title":"Sabır ve rahmet dersi","body":"Allah, Hz. Muhammed’e balık sahibinin yaşadığını hatırlatarak sabretmesini emretti. Yunus’un seçilip salihlerden kılındığı bildirildi.","source":"Kur’an · Kalem 68:48–50"}],"Zekeriya":[{"title":"Meryem’in annesinin adağı","body":"İmrân’ın eşi, doğacak çocuğunu Allah’a hizmet için adadı. Çocuk kız olarak doğunca ona Meryem adını verdi. Allah Meryem’i güzel bir kabul ile kabul etti ve onun bakımını Zekeriya üstlendi.","source":"Kur’an · Âl-i İmrân 3:35–37"},{"title":"Mihraptaki rızık","body":"Zekeriya, Meryem’in bulunduğu mihraba her girişinde yanında rızık buldu. Nereden geldiğini sorduğunda Meryem, bunun Allah katından olduğunu ve Allah’ın dilediğine hesapsız rızık verdiğini söyledi. Kur’an yiyeceklerin türünü belirtmez.","source":"Kur’an · Âl-i İmrân 3:37"},{"title":"Yaşlılıkta yapılan dua","body":"Zekeriya yaşlandığını, kemiklerinin zayıfladığını ve saçlarının ağardığını söyleyerek Allah’a gizlice dua etti. Eşi çocuk sahibi olamıyordu. Kendisinden sonra sorumluluk üstlenecek, Allah’ın razı olacağı bir evlat istedi.","source":"Kur’an · Meryem 19:2–6; Enbiyâ 21:89"},{"title":"Yahya’nın müjdelenmesi","body":"Melekler, namaz kılarken Zekeriya’ya Yahya adında bir oğul müjdeledi. Yahya’nın salih, iffetli ve peygamber olacağı bildirildi. Zekeriya ileri yaşı ve eşinin durumu sebebiyle şaşırdı; Allah için bunun kolay olduğu açıklandı.","source":"Kur’an · Âl-i İmrân 3:39–40; Meryem 19:7–9"},{"title":"Üç gün konuşamama işareti","body":"Zekeriya işaret istedi. İnsanlarla sağlıklı olduğu hâlde üç gün veya üç gece konuşamayacağı bildirildi. İnsanlara işaretlerle sabah akşam Allah’ı tesbih etmelerini söyledi.","source":"Kur’an · Âl-i İmrân 3:41; Meryem 19:10–11"},{"title":"Duanın kabulü ve sonraki hayatı","body":"Allah Zekeriya’ya Yahya’yı verdi, eşini çocuk sahibi olabilecek duruma getirdi. Aile hayırlı işlerde yarışan, umut ve korku içinde dua eden kullar olarak övüldü. Zekeriya’nın ölüm şekli Kur’an’da açıklanmaz.","source":"Kur’an · Enbiyâ 21:89–90; ölümüne dair ayrıntılar Kur’an’da yok"}],"Yahya":[{"title":"Mucizevi doğum","body":"Zekeriya ve çocuk sahibi olamayan eşi ileri yaşta iken Allah onlara Yahya’yı müjdeledi. İsmi ilahî müjdeyle bildirildi. Doğumunun bütün fiziksel ayrıntıları Kur’an’da verilmez.","source":"Kur’an · Meryem 19:7–9; Enbiyâ 21:90"},{"title":"Çocuk yaşta hikmet","body":"Yahya’ya kitaba kuvvetle sarılması emredildi. Allah ona çocuk yaşta hikmet verdi. Tefsirlerde kitabın Tevrat olduğu belirtilir, fakat ilgili ayette kitap ismi açıkça söylenmez.","source":"Kur’an · Meryem 19:12"},{"title":"Şefkat, temizlik ve takva","body":"Yahya’ya Allah katından şefkat ve temizlik verildi; onun takva sahibi olduğu bildirildi. İffetli, seçkin ve salihlerden bir peygamber olarak övüldü.","source":"Kur’an · Meryem 19:13; Âl-i İmrân 3:39"},{"title":"Anne babasına iyiliği","body":"Yahya anne ve babasına iyilik eden biriydi; zorba ve isyankâr değildi. Kur’an onun örnek ahlakını özellikle vurgular.","source":"Kur’an · Meryem 19:14"},{"title":"Doğum, ölüm ve diriliş","body":"Yahya’nın doğduğu, öleceği ve yeniden diriltileceği gün üzerine esenlik bildirildi. Nasıl öldüğü Kur’an’da anlatılmaz; öldürülmesi hakkındaki tarihî rivayetler Kur’an’ın açık kıssası değildir.","source":"Kur’an · Meryem 19:15"}],"İsa":[{"title":"İmrân ailesi ve Meryem’in adağı","body":"İmrân’ın eşi doğacak çocuğunu Allah’a adadı. Meryem dünyaya geldi; Allah onu güzelce yetiştirdi ve bakımını Zekeriya üstlendi. Kur’an Meryem’in annesinin adını belirtmez.","source":"Kur’an · Âl-i İmrân 3:35–37"},{"title":"Meryem’in seçilmesi","body":"Melekler Meryem’e Allah’ın kendisini seçtiğini, temizlediğini ve kadınlara üstün kıldığını bildirdi. Ona ibadet ve teslimiyet emredildi.","source":"Kur’an · Âl-i İmrân 3:42–43"},{"title":"Mihraptaki rızık","body":"Zekeriya, Meryem’in yanında rızık buldu. Meryem bunun Allah katından olduğunu söyledi. Mevsim dışı meyveler gibi ayrıntılar ayette açık değildir.","source":"Kur’an · Âl-i İmrân 3:37"},{"title":"Meleğin görünmesi","body":"Meryem ailesinden uzaklaşıp perde arkasına çekildi. Allah’ın gönderdiği ruh ona insan görünümünde geldi. Meryem Allah’a sığındı; elçi temiz bir erkek çocuk müjdeledi.","source":"Kur’an · Meryem 19:16–19"},{"title":"Babasız doğum müjdesi","body":"Meryem kendisine hiçbir erkek dokunmadığını söyledi. Bunun Allah için kolay olduğu ve çocuğun insanlara bir işaret olacağı bildirildi. İsa’nın adı Mesih İsa olarak müjdelendi.","source":"Kur’an · Meryem 19:20–21; Âl-i İmrân 3:45–47"},{"title":"Hurma ağacının altında doğum","body":"Doğum sancısı Meryem’i hurma ağacına götürdü. Ona üzülmemesi, su içmesi ve ağacı silkeleyip taze hurma yemesi söylendi. Kur’an doğumun kesin tarihini vermez.","source":"Kur’an · Meryem 19:22–26"},{"title":"Kavmine dönüş ve suçlamalar","body":"Meryem bebeğiyle kavmine döndü. İnsanlar onu suçladı. Meryem çocuğu işaret etti; beşikteki çocukla nasıl konuşabileceklerini sordular.","source":"Kur’an · Meryem 19:27–29"},{"title":"Beşikte konuşma mucizesi","body":"İsa Allah’ın kulu olduğunu, kendisine kitap verildiğini, peygamber kılındığını, namaz ve zekâtla emrolunduğunu, annesine iyi davranan biri olduğunu söyledi.","source":"Kur’an · Meryem 19:30–33; Mâide 5:110"},{"title":"Âdem ile benzetilmesi","body":"İsa’nın yaratılışı Âdem’in yaratılışına benzetilir. Babasız yaratılmak ilahlık anlamına gelmez; yaratma kudreti Allah’a aittir.","source":"Kur’an · Âl-i İmrân 3:59"},{"title":"Tevrat, İncil ve tebliğ","body":"İsa’ya kitap, hikmet, Tevrat ve İncil öğretildi. İsrailoğullarına gönderildi; önceki Tevrat’ı doğruladı ve insanları Allah’a kulluğa çağırdı.","source":"Kur’an · Âl-i İmrân 3:48–51; Mâide 5:46"},{"title":"Çamurdan kuş mucizesi","body":"İsa çamurdan kuş biçiminde bir şey yaptı ve ona üfledi; Allah’ın izniyle canlı kuş oldu. Kur’an mucizenin bağımsız bir yaratma gücü değil, Allah’ın izniyle olduğunu vurgular.","source":"Kur’an · Âl-i İmrân 3:49; Mâide 5:110"},{"title":"Körleri ve hastaları iyileştirmesi","body":"Doğuştan kör olanları ve alaca hastalığına yakalananları Allah’ın izniyle iyileştirdi. Kur’an iyileştirilen kişilerin isimlerini vermez.","source":"Kur’an · Âl-i İmrân 3:49; Mâide 5:110"},{"title":"Ölüleri diriltmesi","body":"İsa Allah’ın izniyle ölüleri diriltti. Kur’an diriltilen kişilerin isimlerini açıklamaz; bu mucize hayat verme kudretinin Allah’a ait olduğunu gösterir.","source":"Kur’an · Âl-i İmrân 3:49; Mâide 5:110"},{"title":"Evlerde saklananları bildirmesi","body":"İsa insanlara ne yediklerini ve evlerinde ne sakladıklarını haber verdiğini bildirdi. Bu, kendisine Allah tarafından verilen bir işaret olarak sunulur.","source":"Kur’an · Âl-i İmrân 3:49"},{"title":"Havarilerin desteği","body":"İsa Allah yolunda kendisine kimin yardım edeceğini sordu. Havariler Allah’ın yardımcıları olduklarını, iman ettiklerini ve teslim olduklarını bildirdi. Kur’an isim ve sayılarını vermez.","source":"Kur’an · Âl-i İmrân 3:52–53; Saff 61:14"},{"title":"Gökten sofra isteği","body":"Havariler gökten bir sofra istediler. İsa Allah’a dua ederek bunun bir bayram ve işaret olmasını diledi. Allah sofrayı indireceğini, ardından inkâr edenlere ağır sorumluluk düşeceğini bildirdi. Sofranın içeriği açıklanmaz.","source":"Kur’an · Mâide 5:112–115"},{"title":"Ahmed adlı elçinin müjdelenmesi","body":"İsa, kendisinden sonra Ahmed adlı bir elçi geleceğini müjdeledi. İslamî yorum bu müjdeyi Hz. Muhammed ile ilişkilendirir.","source":"Kur’an · Saff 61:6"},{"title":"Öldürülme iddiası ve yükseltilmesi","body":"Kur’an, İsa’yı öldürdükleri ve çarmıha gerdikleri iddiasını reddeder; Allah’ın onu kendisine yükselttiğini bildirir. Olayın fiziksel ayrıntıları ve yerine geçtiği iddia edilen kişinin kimliği Kur’an’da açıklanmaz.","source":"Kur’an · Nisâ 4:157–158; Âl-i İmrân 3:54–55"},{"title":"Ahiret konuşması","body":"Allah’ın İsa’ya kendisini ve annesini ilah edinmeyi insanlara söyleyip söylemediğini soracağı anlatılır. İsa yalnızca Allah’a kulluğu emrettiğini bildirir ve hükmü Allah’a bırakır.","source":"Kur’an · Mâide 5:116–119"},{"title":"İsa’nın konumu","body":"İsa, Kur’an’da Allah’ın kulu, elçisi ve Mesih olarak tanıtılır. Ahir zamanda dönüşüne dair ayrıntılar özellikle hadislerde bulunur; Kur’an kesin tarih veya ayrıntılı dönüş sahnesi vermez.","source":"Kur’an · Nisâ 4:171–172; Meryem 19:30–36; Zuhruf 43:61 (yorum ihtilaflı)"}],"Muhammed":[{"title":"Fil Yılı ve Mekke","body":"Kureyş’in ticaret yolları ve Kâbe’nin konumu anlatılır. Fil suresi Kâbe’ye saldıran ordunun bozguna uğratılmasını bildirir. Peygamberin yaklaşık 570/571’de Fil Yılı’nda doğduğu siyer geleneğidir; Kur’an doğum yılını vermez.","source":"Kur’an · Fîl 105; Kureyş 106 | Siyer · Doğum yılı"},{"title":"Doğumu ve ailesi","body":"Mekke’de Kureyş’in Hâşimoğulları kolunda doğdu. Babası Abdullah, annesi Âmine idi. Babasını doğumundan önce kaybettiği aktarılır. Allah onu yetim bulup barındırdığını hatırlatır.","source":"Kur’an · Duhâ 93:6–8 | Siyer · Aile ve doğum bilgileri"},{"title":"Sütanne ve çocukluk","body":"Siyer kaynakları sütannesi Halîme’nin yanında yetiştiğini anlatır. Çocuklukta kalbinin temizlenmesiyle ilgili rivayet Sahih Müslim’de geçer. İnşirâh suresindeki göğsün açılması ifadesinin bu olayla ilişkisi yorumludur.","source":"Hadis · Sahih Müslim, Îmân | Kur’an · İnşirâh 94:1–4"},{"title":"Annesi, dedesi ve amcası","body":"Annesi Âmine’yi yaklaşık altı yaşında, dedesi Abdülmuttalib’i yaklaşık sekiz yaşında kaybettiği anlatılır. Amcası Ebû Tâlib onu himaye etti. Kur’an yetimliğini hatırlatır fakat bu tarihleri vermez.","source":"Kur’an · Duhâ 93:6 | Siyer · Çocukluk"},{"title":"Gençliği ve güvenilirliği","body":"Koyun güttüğü sahih hadislerde yer alır. Ticaretle uğraştığı, güvenilirliğiyle tanındığı siyer kaynaklarında anlatılır. Peygamberlikten önce vahiy kitabının ayrıntılarını bilmiyordu.","source":"Hadis · Sahih Buhârî, İcâre | Kur’an · Şûrâ 42:52"},{"title":"Hatice ile evlilik ve çocukları","body":"Hatice ile evlendi; ilk vahiy sırasında en büyük destekçisi oldu. Kāsım, Abdullah, Zeyneb, Rukıyye, Ümmü Külsûm ve Fâtıma’nın annesidir. İbrahim’in annesi Mâriye’dir. Evlilik yaşları hakkındaki rakamlar siyer rivayetlerine dayanır.","source":"Hadis · Sahih Buhârî, Bed’ü’l-vahy | Siyer · Aile"},{"title":"Kâbe hakemliği","body":"Kâbe’nin onarımı sırasında Hacerülesved’in yerine konulması anlaşmazlığını uzlaştırıcı bir yöntemle çözdüğü siyer kaynaklarında anlatılır. Kur’an bu olayı doğrudan vermez.","source":"Siyer · Kâbe’nin onarımı | Kur’an · Bakara 2:127"},{"title":"Hira ve ilk vahiy","body":"Hira Mağarası’nda Cebrâil’in gelişiyle Alak suresinin ilk ayetleri vahyedildi. Peygamber evine dönünce Hatice onu teselli etti; Varaka b. Nevfel ile görüşüldü.","source":"Kur’an · Alak 96:1–5 | Hadis · Sahih Buhârî, Bed’ü’l-vahy"},{"title":"Vahyin yeniden başlaması","body":"İlk vahiyden sonra bir süre kesinti oldu. Müddessir suresinde kalkıp uyarması, Rabbini yüceltmesi ve sabretmesi emredildi.","source":"Kur’an · Müddessir 74:1–7 | Hadis · Sahih Buhârî, Bed’ü’l-vahy"},{"title":"İlk Müslümanlar","body":"Hatice ilk iman eden kişiydi. Ali, Ebû Bekir ve Zeyd b. Hârise ilk Müslümanlar arasında yer aldı. Dârülerkam’daki eğitim ve ilk davetin ayrıntıları siyer kaynaklarında anlatılır.","source":"Siyer · İlk davet | Kur’an · Tevbe 9:100"},{"title":"Açık davet ve Safâ","body":"Yakın akrabalarını uyarması emredildi. Safâ Tepesi’nde Kureyş’i uyardığı sahih hadislerde anlatılır. Ebû Leheb’in düşmanlığı Tebbet suresinde kınandı.","source":"Kur’an · Şuarâ 26:214; Tebbet 111 | Hadis · Sahih Buhârî, Tefsir"},{"title":"Mekke baskıları","body":"İlk Müslümanlar alay, dışlama ve işkenceyle karşılaştı. Kur’an yalanlama ve baskıları anlatır; Bilâl, Ammâr ve diğerlerinin yaşadıkları hadis ve siyer kaynaklarında yer alır.","source":"Kur’an · Ankebût 29:2–3; Nahl 16:106 | Siyer · Mekke dönemi"},{"title":"Habeşistan hicreti","body":"Müslümanların bir bölümü güvenlik için Habeşistan’a göç etti. Necâşî’nin himayesi ve Ca’fer’in konuşması siyer geleneğinde aktarılır. Kur’an bu hicreti isim ve tarihle anlatmaz.","source":"Siyer · Habeşistan hicreti | Kur’an · Nahl 16:41"},{"title":"Hamza, Ömer ve boykot","body":"Hamza ve Ömer’in Müslüman oluşu, Hâşimoğullarına yönelik boykot ve ekonomik sıkıntılar siyer kaynaklarında yer alır. Ayrıntıların rivayet dereceleri farklıdır.","source":"Siyer · Mekke dönemi"},{"title":"Hüzün Yılı ve Tâif","body":"Hatice ve Ebû Tâlib’in vefatıyla destekleri azaldı. Tâif’te reddedildi; sahih hadiste düşmanlarına hemen azap istemeyip onların soyundan iman edenler çıkmasını umduğu anlatılır.","source":"Kur’an · Kasas 28:56 | Hadis · Sahih Buhârî ve Müslim"},{"title":"İsrâ ve Mi’rac","body":"Kur’an gece yolculuğunu Mescid-i Harâm’dan Mescid-i Aksâ’ya olarak anlatır. Göğe yükseliş ve namazın farz kılınmasının ayrıntıları sahih hadislerde yer alır.","source":"Kur’an · İsrâ 17:1 | Hadis · Sahih Buhârî ve Müslim"},{"title":"Akabe biatları","body":"Yesribli Müslümanlarla yapılan biatlar Medine’ye hicretin yolunu açtı. Mus’ab b. Umeyr Medine’ye öğretici olarak gönderildi. Ayrıntılar siyer kaynaklarındadır.","source":"Siyer · Akabe biatları"},{"title":"Hicret ve Sevr Mağarası","body":"Müşriklerin planlarına karşı Ebû Bekir ile hicret etti. Kur’an mağarada iki kişiden ve “Allah bizimle beraberdir” tesellisinden söz eder.","source":"Kur’an · Enfâl 8:30; Tevbe 9:40 | Hadis · Sahih Buhârî"},{"title":"Medine toplumunun kuruluşu","body":"622’de Medine’ye yerleşti. Mescid-i Nebevî inşa edildi; muhacirlerle ensar arasında dayanışma kuruldu. Medine Vesikası siyer kaynaklarında aktarılır.","source":"Kur’an · Haşr 59:8–9; Hucurât 49:10 | Siyer · Medine Vesikası"},{"title":"Kıblenin değişmesi","body":"Namaz yönü Kudüs’ten Mescid-i Harâm’a çevrildi. Kur’an, kıble değişimine yönelik soruları ve yeni emri ayrıntılı biçimde ele alır.","source":"Kur’an · Bakara 2:142–150"},{"title":"Bedir Savaşı","body":"624’te Müslümanlar Bedir’de Mekke ordusuyla karşılaştı ve galip geldi. Kur’an meleklerle yardım, dua, esirler ve ganimetlerle ilgili hükümleri anlatır.","source":"Kur’an · Enfâl 8:1–19, 67–71; Âl-i İmrân 3:123–127"},{"title":"Uhud Savaşı","body":"625’te Uhud’da okçuların bir bölümünün mevzilerini terk etmesi savaşın seyrini değiştirdi. Hamza şehit oldu; Peygamber yaralandı. Kur’an disiplin, sabır ve hatalardan ders çıkarmayı vurgular.","source":"Kur’an · Âl-i İmrân 3:121–180"},{"title":"Benî Nadîr ve diğer gerilimler","body":"Medine’de Benî Kaynukā, Benî Nadîr ve diğer gruplarla anlaşmazlıklar yaşandı. Haşr suresi Benî Nadîr’in çıkarılmasıyla bağlantılıdır. Recî ve Bi’rimaûne olayları hadis ve siyer kaynaklarında anlatılır.","source":"Kur’an · Haşr 59:2–10 | Hadis/Siyer · Diğer olaylar"},{"title":"Hendek ve Benî Kurayza","body":"627’de müttefik ordular Medine’yi kuşattı. Hendek savunması yapıldı. Kur’an kuşatmanın korkusunu ve Allah’ın yardımını anlatır. Ardından Benî Kurayza ile ağır bir çatışma yaşandı.","source":"Kur’an · Ahzâb 33:9–27 | Siyer · Ayrıntılar"},{"title":"Benî Mustalik ve İfk","body":"Benî Mustalik seferiyle bağlantılı dönüşte Âişe hakkında iftira yayıldı. Nûr suresi iftirayı reddetti ve delilsiz suçlamalardan sakındırdı.","source":"Kur’an · Nûr 24:11–26 | Hadis · Sahih Buhârî ve Müslim"},{"title":"Hudeybiye Antlaşması","body":"628’de umre için yola çıkan Müslümanlar Mekke’ye alınmadı. Rıdvan Biatı ve Hudeybiye Antlaşması gerçekleşti. Fetih suresi bunu apaçık fetih olarak nitelendirdi.","source":"Kur’an · Fetih 48:1–29 | Siyer · Antlaşma maddeleri"},{"title":"Hayber, Mûte ve mektuplar","body":"Hayber’in alınması, hükümdarlara gönderilen davet mektupları ve Mûte’de komutanların şehit olması bu dönemin önemli olaylarıdır. Ayrıntılar hadis ve siyer kaynaklarındadır.","source":"Kur’an · Fetih 48:18–21 (tefsir bağlantısı) | Hadis/Siyer"},{"title":"Mekke’nin fethi","body":"630’da Mekke büyük ölçüde sınırlı çatışmayla alındı. Kâbe çevresindeki putlar kaldırıldı. Nasr suresi fetih karşısında tesbih ve istiğfarı emreder.","source":"Kur’an · Nasr 110; İsrâ 17:81 | Hadis · Sahih Buhârî"},{"title":"Huneyn ve Tâif","body":"Huneyn’de başlangıçta çözülme yaşandı; Allah’ın yardımıyla müminler toparlandı. Ardından Tâif kuşatması yapıldı.","source":"Kur’an · Tevbe 9:25–27 | Siyer · Tâif kuşatması"},{"title":"Tebük ve üç kişinin tövbesi","body":"630’daki Tebük seferinde büyük zorluklar yaşandı. Ka’b b. Mâlik ve iki sahabi sefere katılmadıklarını dürüstçe açıkladı; bir süre sonra tövbeleri kabul edildi.","source":"Kur’an · Tevbe 9:38–118 | Hadis · Sahih Buhârî ve Müslim"},{"title":"Mescid-i Dırâr","body":"Bazı kişiler müminler arasında ayrılık çıkarmak amacıyla mescit kurdu. Kur’an Peygamber’e orada namaz kılmamasını emretti.","source":"Kur’an · Tevbe 9:107–110"},{"title":"Eşleri ve aile hayatı","body":"Eşleri müminlerin anneleri olarak anılır. Hatice, Sevde, Âişe, Hafsa, Zeyneb bint Huzeyme, Ümmü Seleme, Zeyneb bint Cahş, Cüveyriye, Ümmü Habîbe, Safiyye ve Meymûne ile evlendi. Mâriye, oğlu İbrahim’in annesidir; statüsü farklı değerlendirilir.","source":"Kur’an · Ahzâb 33:6, 28–34, 37, 50–53; Tahrîm 66:1–5 | Siyer · Eşlerin isimleri"},{"title":"Zeyd ve Zeyneb meselesi","body":"Zeyd b. Hârise’nin Zeyneb bint Cahş ile evliliği sona erdi. Peygamber’in Zeyneb ile evliliği evlatlıkla biyolojik oğul arasındaki hukukî fark bağlamında açıklandı.","source":"Kur’an · Ahzâb 33:4–5, 37–40"},{"title":"Çocukları ve torunları","body":"Hatice’den Kāsım, Abdullah, Zeyneb, Rukıyye, Ümmü Külsûm ve Fâtıma; Mâriye’den İbrahim dünyaya geldi. Fâtıma’nın çocukları Hasan ve Hüseyin’dir. İbrahim’in ölümündeki güneş tutulmasının onun ölümüyle ilgili olmadığını Peygamber açıkladı.","source":"Hadis · Sahih Buhârî ve Müslim, Küsûf | Siyer · Aile"},{"title":"Mucize: Kur’an","body":"Kur’an kendisini vahiy olarak sunar; benzerini getirme çağrısında bulunur. İslam inancında Peygamber’in en büyük ve sürekli mucizesi Kur’an’dır.","source":"Kur’an · Bakara 2:23–24; İsrâ 17:88; Ankebût 29:50–51"},{"title":"Diğer mucizeler","body":"Ayın yarılması Kamer suresinde geçer ve sahih hadislerde anlatılır. Parmaklardan su akması, yiyecek bereketi ve hurma kütüğünün inlemesi sahih hadis rivayetlerindendir; Kur’an bunları ayrı ayrı anlatmaz.","source":"Kur’an · Kamer 54:1–2 | Hadis · Sahih Buhârî ve Müslim"},{"title":"Veda Haccı","body":"632’de Veda Haccı’nı yaptı. Arafat, Müzdelife ve Mina’daki uygulamalar Sahih Müslim’de Câbir’in uzun rivayetinde anlatılır.","source":"Kur’an · Bakara 2:196–203; Hac 22:26–37 | Hadis · Sahih Müslim, Hac"},{"title":"Veda Hutbesi","body":"Can, mal ve namus dokunulmazlığını, emanetleri ve aile sorumluluklarını vurguladı. Günümüzde tek metin olarak dolaşan uzun hutbe farklı rivayetlerin birleşimi olabilir.","source":"Hadis · Sahih Buhârî ve Müslim, Hac"},{"title":"Dinin tamamlanması","body":"Mâide 5:3 ayetinde dinin kemale erdirildiği bildirildi. Sahih rivayetlerde ayetin Arafat’ta indiği anlatılır. Kur’an’ın kesin son ayeti olduğu söylenemez.","source":"Kur’an · Mâide 5:3 | Hadis · Sahih Buhârî ve Müslim"},{"title":"Son hastalığı","body":"Hicri 11’de hastalandı. Son günlerinde Âişe’nin odasında kaldı. Ebû Bekir’in namaz kıldırmasını istediği sahih hadislerde anlatılır.","source":"Hadis · Sahih Buhârî ve Müslim, Salât ve Megâzî"},{"title":"Vefatı ve defin","body":"632’de Medine’de vefat etti. Ebû Bekir, Âl-i İmrân 3:144 ayetini okuyarak Peygamber’in de ölümlü olduğunu hatırlattı. Âişe’nin odasına defnedildi. Kesin vefat günü hakkında tarihî görüşler farklıdır.","source":"Kur’an · Âl-i İmrân 3:144; Zümer 39:30 | Hadis/Siyer"},{"title":"Yüce ahlakı ve son peygamber oluşu","body":"Kur’an onun yüce ahlakını, merhametini, güzel örnekliğini ve peygamberlerin sonuncusu olduğunu bildirir. İnsanlara Allah’a kulluğu, adaleti ve sorumluluğu öğretti.","source":"Kur’an · Kalem 68:4; Ahzâb 33:21, 40; Enbiyâ 21:107"}]};
const prophetDataReady = Promise.resolve(prophetStories);

let selectedProphet=null,prophetPage=0;
function renderProphetCards(panel){
 const list=document.createElement('div');list.className='prophet-list';
 prophets.forEach((name,i)=>{
  const row=document.createElement('div');row.className='prophet-card';
  const cb=document.createElement('input');cb.type='checkbox';cb.checked=check('peygamber:'+(i+1));cb.setAttribute('aria-label',name+' okundu');
  cb.onchange=()=>{setCheck('peygamber:'+(i+1),cb.checked);panel.dispatchEvent(new Event('prophet-update'))};
  const b=document.createElement('button');b.type='button';b.className='prophet-open';b.textContent=(i+1)+'. '+name+' — Hayatını oku →';b.onclick=()=>openProphet(name);
  row.append(cb,b);list.append(row);
 });panel.append(list);
}
function addProphetProgress(panel){const p=document.createElement('p');p.className='hint live-progress';panel.insertBefore(p,panel.querySelector('.prophet-list'));
 function update(){const done=prophets.filter((_,i)=>check('peygamber:'+(i+1))).length;p.textContent=`Okunan: ${done} / 25 · %${Math.round(done/25*100)}`};
 panel.addEventListener('prophet-update',update);update();
}
async function openProphet(name){
 selectedProphet=name;show('prophetReader');
 $('prophetReaderTitle').textContent=name+' Peygamber';
 $('prophetReaderSubtitle').textContent='Bölümler yükleniyor…';
 try {await prophetDataReady;}catch(e){$('prophetReaderSubtitle').textContent='İçerik yüklenemedi. İnternet bağlantını kontrol edip sayfayı yenile.';return;}
 const saved=Number(localStorage.getItem('peygamber-sayfa:'+name)||0);
 prophetPage=Math.min(Math.max(saved,0),(prophetStories[name]||[]).length-1);renderProphetPage();
}
function renderProphetPage(){
 if(!selectedProphet)return;const pages=prophetStories[selectedProphet];if(!pages||!pages.length)return;
 prophetPage=Math.max(0,Math.min(prophetPage,pages.length-1));
 const chapter=pages[prophetPage];
 $('prophetReaderTitle').textContent=selectedProphet+' Peygamber';
 $('prophetReaderSubtitle').textContent=pages.length+' bölüm · Kur’an / hadis / siyer kaynak ayrımı · Kaldığın yer kaydedilir';
 const root=$('prophetReaderText');root.replaceChildren();
 const h=document.createElement('h2');h.textContent=(prophetPage+1)+'. '+chapter.title;
 const p=document.createElement('p');p.textContent=chapter.body;
 const src=document.createElement('p');src.className='prophet-source';src.textContent='Kaynak: '+chapter.source;
 root.append(h,p,src);
 $('prophetPageLabel').textContent=(prophetPage+1)+' / '+pages.length;
 $('prophetPrev').disabled=prophetPage===0;$('prophetNext').disabled=prophetPage===pages.length-1;
 localStorage.setItem('peygamber-sayfa:'+selectedProphet,String(prophetPage));
 window.scrollTo(0,0);
}
$('prophetPrev').onclick=()=>{if(prophetPage>0){prophetPage--;renderProphetPage()}};
$('prophetNext').onclick=()=>{const pages=prophetStories[selectedProphet]||[];if(prophetPage<pages.length-1){prophetPage++;renderProphetPage()}};
$('backProphets').onclick=()=>{show('more');requestAnimationFrame(()=>document.getElementById('prophetPanel')?.scrollIntoView({block:'start'}))};

show('home');
